-- Aprenda se Divertindo · 74 · Cartões da trilha Policial · parte 2 de 5 (cartões 1000101 a 1000200)
-- Cole no SQL Editor e clique em Run. Pode rodar de novo sem problema. Rode as partes em ordem (a parte 1 cria a tabela).

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 1000101, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pares", "frente": "Renúncia x perdão do ofendido.", "verso": "Renúncia: antes da queixa e unilateral. Perdão: depois de iniciada a ação e bilateral (precisa ser aceito).", "explicacao": "CP, arts. 104 a 106."}, {"id": 1000102, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Qual a regra geral de competência territorial no CPP?", "verso": "O lugar em que se consumou a infração; na tentativa, o lugar do último ato de execução.", "explicacao": "CPP, art. 70 (teoria do resultado)."}, {"id": 1000103, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Qual a competência constitucional do Tribunal do Júri?", "verso": "Julgar os crimes dolosos contra a vida, tentados ou consumados, e os conexos.", "explicacao": "CF, art. 5º, XXXVIII, d."}, {"id": 1000104, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quais os princípios constitucionais do júri?", "verso": "Plenitude de defesa, sigilo das votações, soberania dos veredictos e competência para os crimes dolosos contra a vida.", "explicacao": "CF, art. 5º, XXXVIII."}, {"id": 1000105, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quais as quatro decisões possíveis ao fim da primeira fase do júri?", "verso": "Pronúncia, impronúncia, desclassificação e absolvição sumária.", "explicacao": "CPP, arts. 413 a 419."}, {"id": 1000106, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pares", "frente": "Recurso cabível: contra pronúncia x contra impronúncia ou absolvição sumária.", "verso": "Pronúncia: recurso em sentido estrito. Impronúncia e absolvição sumária: apelação.", "explicacao": "CPP, arts. 581, IV, e 416."}, {"id": 1000107, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Qual o prazo da apelação e do recurso em sentido estrito?", "verso": "5 dias para interpor.", "explicacao": "CPP, arts. 593 e 586."}, {"id": 1000108, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "certo_errado", "frente": "Certo ou errado? Em recurso exclusivo da defesa, o tribunal pode piorar a situação do réu.", "verso": "Errado. É vedada a reformatio in pejus.", "explicacao": "CPP, art. 617."}, {"id": 1000109, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Quando cabe revisão criminal?", "verso": "A qualquer tempo, antes ou depois de extinta a pena, e só em favor do réu.", "explicacao": "CPP, arts. 621 e 622."}, {"id": 1000110, "trilha": "policial", "materia": "ppen", "assunto": "Habeas corpus", "tipo": "pergunta", "frente": "Quando cabe habeas corpus?", "verso": "Sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder.", "explicacao": "CF, art. 5º, LXVIII."}, {"id": 1000111, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "O que acontece com a prova ilícita e a derivada dela?", "verso": "São inadmissíveis e devem ser desentranhadas, salvo quando não houver nexo de causalidade ou a derivada puder ser obtida por fonte independente.", "explicacao": "CF, art. 5º, LVI, e CPP, art. 157 (frutos da árvore envenenada)."}, {"id": 1000112, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "O que é cadeia de custódia?", "verso": "O conjunto de procedimentos para manter e documentar a história cronológica do vestígio, do reconhecimento ao descarte.", "explicacao": "CPP, art. 158-A (Pacote Anticrime)."}, {"id": 1000113, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "certo_errado", "frente": "Certo ou errado? Quando a infração deixa vestígios, a confissão pode suprir o exame de corpo de delito.", "verso": "Errado. O exame é indispensável e a confissão não o supre.", "explicacao": "CPP, art. 158. Se os vestígios desaparecerem, a prova testemunhal pode supri-lo (art. 167)."}, {"id": 1000114, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quantos peritos fazem o exame de corpo de delito?", "verso": "Um perito oficial com diploma de curso superior. Na falta, duas pessoas idôneas com diploma superior.", "explicacao": "CPP, art. 159."}, {"id": 1000115, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quando se pode entrar numa casa durante a noite sem consentimento?", "verso": "Em flagrante delito, desastre ou para prestar socorro. Por ordem judicial, só durante o dia.", "explicacao": "CF, art. 5º, XI."}, {"id": 1000116, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Requisitos da interceptação telefônica.", "verso": "Ordem judicial, indícios razoáveis de autoria, crime punido com reclusão e impossibilidade de obter a prova por outros meios. Prazo de 15 dias, renovável.", "explicacao": "Lei 9.296/1996, arts. 2º e 5º."}, {"id": 1000117, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Como deve ser feito o reconhecimento de pessoas?", "verso": "A testemunha descreve a pessoa; o suspeito é colocado ao lado de outras parecidas; lavra-se auto pormenorizado.", "explicacao": "CPP, art. 226. O STJ considera essas formalidades garantia mínima do suspeito."}, {"id": 1000118, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quais as características da confissão no CPP?", "verso": "É retratável e divisível, e vale em conjunto com as demais provas.", "explicacao": "CPP, arts. 197 e 200."}, {"id": 1000119, "trilha": "policial", "materia": "ppen", "assunto": "Interrogatório", "tipo": "certo_errado", "frente": "Certo ou errado? O silêncio do acusado pode ser interpretado em prejuízo da defesa.", "verso": "Errado.", "explicacao": "CF, art. 5º, LXIII, e CPP, art. 186, parágrafo único."}, {"id": 1000120, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "No procedimento comum, em que momento ocorre o interrogatório?", "verso": "É o último ato da instrução.", "explicacao": "CPP, art. 400."}, {"id": 1000121, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pares", "frente": "Procedimento ordinário x sumário x sumaríssimo: critério.", "verso": "Ordinário: pena máxima igual ou superior a 4 anos. Sumário: inferior a 4 anos. Sumaríssimo: infrações de menor potencial ofensivo.", "explicacao": "CPP, art. 394, § 1º."}, {"id": 1000122, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pares", "frente": "Número de testemunhas: ordinário x sumário.", "verso": "Ordinário: até 8 por parte. Sumário: até 5.", "explicacao": "CPP, arts. 401 e 532."}, {"id": 1000123, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Acusado citado por edital não comparece nem constitui advogado. E agora?", "verso": "Ficam suspensos o processo e o curso do prazo prescricional.", "explicacao": "CPP, art. 366."}, {"id": 1000124, "trilha": "policial", "materia": "ppen", "assunto": "Sentença", "tipo": "pares", "frente": "Emendatio libelli x mutatio libelli.", "verso": "Emendatio: o juiz dá nova definição jurídica ao mesmo fato descrito. Mutatio: surge prova de elemento ou circunstância não descrita, e o MP deve aditar a denúncia.", "explicacao": "CPP, arts. 383 e 384."}, {"id": 1000125, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "O que é infração de menor potencial ofensivo?", "verso": "Contravenções penais e crimes com pena máxima não superior a 2 anos.", "explicacao": "Lei 9.099/1995, art. 61."}, {"id": 1000126, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "Requisito de pena para a suspensão condicional do processo:", "verso": "Pena mínima cominada igual ou inferior a 1 ano. Período de prova de 2 a 4 anos.", "explicacao": "Lei 9.099/1995, art. 89."}, {"id": 1000127, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "Nas infrações de menor potencial ofensivo, o que a polícia lavra em vez do auto de prisão?", "verso": "O termo circunstanciado. Não se impõe prisão em flagrante se o autor se comprometer a comparecer ao juizado.", "explicacao": "Lei 9.099/1995, art. 69."}, {"id": 1000128, "trilha": "policial", "materia": "ppen", "assunto": "ANPP", "tipo": "pergunta", "frente": "Requisitos do acordo de não persecução penal.", "verso": "Infração sem violência ou grave ameaça, pena mínima inferior a 4 anos e confissão formal e circunstanciada, sendo suficiente para reprovação e prevenção do crime.", "explicacao": "CPP, art. 28-A."}, {"id": 1000129, "trilha": "policial", "materia": "ppen", "assunto": "Juiz das garantias", "tipo": "pergunta", "frente": "Qual a função do juiz das garantias?", "verso": "Controlar a legalidade da investigação criminal e salvaguardar os direitos individuais do investigado.", "explicacao": "CPP, art. 3º-B, considerado constitucional pelo STF (ADIs 6.298 e outras)."}, {"id": 1000130, "trilha": "policial", "materia": "ppen", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Qual a natureza da colaboração premiada?", "verso": "Negócio jurídico processual e meio de obtenção de prova.", "explicacao": "Lei 12.850/2013, art. 3º-A."}, {"id": 1000131, "trilha": "policial", "materia": "ppen", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "A infiltração de agentes depende de quê? Qual o prazo?", "verso": "De autorização judicial circunstanciada. Prazo de até 6 meses, renovável.", "explicacao": "Lei 12.850/2013, art. 10."}, {"id": 1000132, "trilha": "policial", "materia": "ppen", "assunto": "Algemas", "tipo": "pergunta", "frente": "Quando o uso de algemas é lícito (Súmula Vinculante 11)?", "verso": "Em caso de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, justificado por escrito.", "explicacao": "Súmula Vinculante 11 do STF."}, {"id": 1000133, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Quais são as formas de notitia criminis?", "verso": "De cognição imediata (a polícia sabe por suas atividades), mediata (por comunicação formal) e coercitiva (prisão em flagrante).", "explicacao": "Doutrina sobre o início do inquérito."}, {"id": 1000134, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O sigilo do inquérito existe para quê?", "verso": "Para a elucidação do fato ou por exigência do interesse da sociedade.", "explicacao": "CPP, art. 20."}, {"id": 1000135, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pergunta", "frente": "Quais são os fundamentos da República (art. 1º)?", "verso": "Soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político.", "explicacao": "CF, art. 1º. Mnemônico SOCIDIVAPLU."}, {"id": 1000136, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pergunta", "frente": "Quais são os Poderes da União?", "verso": "Legislativo, Executivo e Judiciário, independentes e harmônicos entre si.", "explicacao": "CF, art. 2º."}, {"id": 1000137, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pares", "frente": "Fundamentos (art. 1º) x objetivos (art. 3º): como diferenciar?", "verso": "Fundamentos são substantivos (soberania, cidadania…). Objetivos começam com verbos: construir, garantir, erradicar, promover.", "explicacao": "CF, arts. 1º e 3º."}, {"id": 1000138, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A quem o caput do art. 5º garante os direitos fundamentais?", "verso": "Aos brasileiros e aos estrangeiros residentes no País (o STF estende aos não residentes).", "explicacao": "CF, art. 5º, caput."}, {"id": 1000139, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "“A casa é asilo ____ do indivíduo, ninguém nela podendo penetrar sem consentimento do morador…”", "verso": "inviolável", "explicacao": "CF, art. 5º, XI."}, {"id": 1000140, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quais as exceções à inviolabilidade do sigilo das comunicações telefônicas?", "verso": "Por ordem judicial, nas hipóteses e forma que a lei estabelecer, para investigação criminal ou instrução processual penal.", "explicacao": "CF, art. 5º, XII, e Lei 9.296/1996."}, {"id": 1000141, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Em que hipóteses alguém pode ser preso?", "verso": "Em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente (salvo transgressão militar e crime propriamente militar).", "explicacao": "CF, art. 5º, LXI."}, {"id": 1000142, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Que direitos o preso tem no momento da prisão?", "verso": "Ser informado de seus direitos, inclusive o de permanecer calado; assistência da família e de advogado; identificação dos responsáveis pela prisão.", "explicacao": "CF, art. 5º, LXIII e LXIV."}, {"id": 1000143, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Que prisão civil por dívida a Constituição admite e qual o STF aceita hoje?", "verso": "A CF prevê a do devedor de alimentos e a do depositário infiel, mas só a do devedor voluntário e inescusável de alimentos é admitida.", "explicacao": "CF, art. 5º, LXVII, e Súmula Vinculante 25."}, {"id": 1000144, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "certo_errado", "frente": "Certo ou errado? No Brasil pode haver pena de morte em caso de guerra declarada.", "verso": "Certo. É a única exceção.", "explicacao": "CF, art. 5º, XLVII, a."}, {"id": 1000145, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quais penas a Constituição proíbe?", "verso": "De morte (salvo guerra declarada), de caráter perpétuo, de trabalhos forçados, de banimento e cruéis.", "explicacao": "CF, art. 5º, XLVII."}, {"id": 1000146, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "certo_errado", "frente": "Certo ou errado? O brasileiro nato pode ser extraditado se comprovado envolvimento em tráfico de drogas.", "verso": "Errado. O brasileiro nato nunca é extraditado. O naturalizado pode ser, por crime comum antes da naturalização ou por tráfico de drogas.", "explicacao": "CF, art. 5º, LI."}, {"id": 1000147, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "certo_errado", "frente": "Certo ou errado? A reunião pacífica em local aberto depende de autorização prévia.", "verso": "Errado. Basta aviso prévio à autoridade competente.", "explicacao": "CF, art. 5º, XVI."}, {"id": 1000148, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Associação pode ser dissolvida compulsoriamente por quê?", "verso": "Só por decisão judicial transitada em julgado. Para suspender atividades, basta decisão judicial.", "explicacao": "CF, art. 5º, XIX."}, {"id": 1000149, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A lei pode retroagir para prejudicar o quê?", "verso": "Não pode prejudicar o direito adquirido, o ato jurídico perfeito e a coisa julgada.", "explicacao": "CF, art. 5º, XXXVI."}, {"id": 1000150, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pares", "frente": "Habeas corpus x habeas data.", "verso": "Habeas corpus: protege a liberdade de locomoção. Habeas data: garante conhecer ou retificar informações pessoais em bancos de dados públicos.", "explicacao": "CF, art. 5º, LXVIII e LXXII."}, {"id": 1000151, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pares", "frente": "Mandado de segurança x mandado de injunção.", "verso": "Segurança: protege direito líquido e certo não amparado por HC ou HD. Injunção: quando falta norma regulamentadora que torna inviável o exercício de um direito.", "explicacao": "CF, art. 5º, LXIX e LXXI."}, {"id": 1000152, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pergunta", "frente": "Quem pode propor ação popular?", "verso": "Qualquer cidadão (eleitor).", "explicacao": "CF, art. 5º, LXXIII. Isento de custas, salvo má-fé."}, {"id": 1000153, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pergunta", "frente": "Quais ações são gratuitas por força da Constituição?", "verso": "Habeas corpus e habeas data e, na forma da lei, os atos necessários ao exercício da cidadania.", "explicacao": "CF, art. 5º, LXXVII."}, {"id": 1000154, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Tratados de direitos humanos aprovados com rito de emenda têm que status?", "verso": "Equivalem a emendas constitucionais: 3/5 dos votos, em dois turnos, em cada Casa.", "explicacao": "CF, art. 5º, § 3º."}, {"id": 1000155, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "pergunta", "frente": "Quais cargos são privativos de brasileiro nato?", "verso": "Presidente e Vice; Presidentes da Câmara e do Senado; Ministro do STF; carreira diplomática; oficial das Forças Armadas; Ministro de Estado da Defesa.", "explicacao": "CF, art. 12, § 3º. Mnemônico MP3.COM."}, {"id": 1000156, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Quem é obrigado e quem é facultado a votar?", "verso": "Obrigatório: maiores de 18 anos. Facultativo: analfabetos, maiores de 70 e quem tem entre 16 e 18 anos.", "explicacao": "CF, art. 14, § 1º."}, {"id": 1000157, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Qual a idade mínima para Presidente e para Senador?", "verso": "35 anos.", "explicacao": "CF, art. 14, § 3º, VI, a. Governador: 30; Deputado e Prefeito: 21; Vereador: 18."}, {"id": 1000158, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "certo_errado", "frente": "Certo ou errado? A Constituição admite a cassação de direitos políticos.", "verso": "Errado. É vedada a cassação. Admite-se perda ou suspensão nos casos do art. 15.", "explicacao": "CF, art. 15."}, {"id": 1000159, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "Quais são os entes da Federação?", "verso": "União, Estados, Distrito Federal e Municípios, todos autônomos.", "explicacao": "CF, art. 18. Territórios não são entes federativos."}, {"id": 1000160, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Quais os princípios expressos da Administração Pública?", "verso": "Legalidade, impessoalidade, moralidade, publicidade e eficiência.", "explicacao": "CF, art. 37, caput. Mnemônico LIMPE."}, {"id": 1000161, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual o prazo de validade do concurso público?", "verso": "Até 2 anos, prorrogável uma vez por igual período.", "explicacao": "CF, art. 37, III."}, {"id": 1000162, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "O servidor efetivo adquire estabilidade após quanto tempo?", "verso": "3 anos de efetivo exercício, com avaliação especial de desempenho.", "explicacao": "CF, art. 41."}, {"id": 1000163, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "O servidor estável pode perder o cargo em que casos?", "verso": "Sentença judicial transitada em julgado, processo administrativo com ampla defesa, avaliação periódica de desempenho insuficiente ou excesso de despesa com pessoal.", "explicacao": "CF, arts. 41, § 1º, e 169, § 4º."}, {"id": 1000164, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual a regra de responsabilidade civil do Estado?", "verso": "Objetiva: as pessoas jurídicas de direito público e as privadas prestadoras de serviço público respondem pelos danos que seus agentes causarem, com direito de regresso em caso de dolo ou culpa.", "explicacao": "CF, art. 37, § 6º."}, {"id": 1000165, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "certo_errado", "frente": "Certo ou errado? A Constituição permite acumular dois cargos de professor, se houver compatibilidade de horários.", "verso": "Certo.", "explicacao": "CF, art. 37, XVI. Também: professor + técnico/científico; dois cargos privativos de profissionais de saúde."}, {"id": 1000166, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "lacuna", "frente": "“A segurança pública, dever do Estado, direito e ____ de todos, é exercida para a preservação da ordem pública e da incolumidade das pessoas e do patrimônio.”", "verso": "responsabilidade", "explicacao": "CF, art. 144, caput."}, {"id": 1000167, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Quais órgãos estão listados no art. 144 da Constituição?", "verso": "Polícia Federal, Polícia Rodoviária Federal, Polícia Ferroviária Federal, polícias civis, polícias militares e corpos de bombeiros militares, e polícias penais federal, estaduais e distrital.", "explicacao": "CF, art. 144, I a VI (polícias penais incluídas pela EC 104/2019)."}, {"id": 1000168, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função das polícias civis?", "verso": "Funções de polícia judiciária e apuração de infrações penais, exceto as militares, ressalvada a competência da União.", "explicacao": "CF, art. 144, § 4º. São dirigidas por delegados de polícia de carreira."}, {"id": 1000169, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função das polícias militares?", "verso": "Polícia ostensiva e preservação da ordem pública.", "explicacao": "CF, art. 144, § 5º."}, {"id": 1000170, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "A quem se subordinam as polícias militares e civis?", "verso": "Aos Governadores dos Estados, do DF e dos Territórios.", "explicacao": "CF, art. 144, § 6º. PM e bombeiros são forças auxiliares e reserva do Exército."}, {"id": 1000171, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Cite atribuições da Polícia Federal.", "verso": "Apurar infrações contra a União e com repercussão interestadual ou internacional; prevenir e reprimir tráfico de drogas, contrabando e descaminho; polícia marítima, aeroportuária e de fronteiras; polícia judiciária da União com exclusividade.", "explicacao": "CF, art. 144, § 1º."}, {"id": 1000172, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função da Polícia Rodoviária Federal?", "verso": "Patrulhamento ostensivo das rodovias federais.", "explicacao": "CF, art. 144, § 2º."}, {"id": 1000173, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "O que os Municípios podem constituir na área de segurança?", "verso": "Guardas municipais destinadas à proteção de seus bens, serviços e instalações.", "explicacao": "CF, art. 144, § 8º. O STF reconhece as guardas como integrantes do sistema de segurança pública."}, {"id": 1000174, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função das polícias penais?", "verso": "A segurança dos estabelecimentos penais.", "explicacao": "CF, art. 144, § 5º-A (EC 104/2019)."}, {"id": 1000175, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pares", "frente": "Estado de defesa x estado de sítio: quem autoriza?", "verso": "Estado de defesa: decretado pelo Presidente e submetido ao Congresso em 24 horas. Estado de sítio: depende de autorização prévia do Congresso.", "explicacao": "CF, arts. 136 e 137."}, {"id": 1000176, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pergunta", "frente": "Qual a duração do estado de defesa?", "verso": "Até 30 dias, prorrogável uma vez por igual período.", "explicacao": "CF, art. 136, § 2º."}, {"id": 1000177, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quantos senadores cada Estado elege e por quanto tempo?", "verso": "Três senadores, com mandato de 8 anos, renovando-se a representação de 4 em 4 anos, alternadamente, por 1/3 e 2/3.", "explicacao": "CF, art. 46."}, {"id": 1000178, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quem tem iniciativa para propor emenda à Constituição?", "verso": "1/3 da Câmara ou do Senado, o Presidente da República ou mais da metade das Assembleias Legislativas (cada uma por maioria relativa).", "explicacao": "CF, art. 60."}, {"id": 1000179, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Qual o quórum de aprovação de emenda constitucional?", "verso": "3/5 dos votos, em dois turnos, em cada Casa do Congresso.", "explicacao": "CF, art. 60, § 2º."}, {"id": 1000180, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quais são as cláusulas pétreas?", "verso": "Forma federativa de Estado; voto direto, secreto, universal e periódico; separação dos Poderes; direitos e garantias individuais.", "explicacao": "CF, art. 60, § 4º. Mnemônico FO.VO.SE.DI."}, {"id": 1000181, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quais poderes as CPIs têm?", "verso": "Poderes de investigação próprios das autoridades judiciais. As conclusões vão ao MP para promover a responsabilidade.", "explicacao": "CF, art. 58, § 3º. CPI não pode decretar prisão (salvo flagrante) nem interceptação telefônica."}, {"id": 1000182, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Qual o quórum para aprovar lei complementar?", "verso": "Maioria absoluta.", "explicacao": "CF, art. 69. Lei ordinária: maioria simples."}, {"id": 1000183, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Medida provisória: prazo de vigência.", "verso": "60 dias, prorrogável uma vez por mais 60. O prazo não corre no recesso.", "explicacao": "CF, art. 62, §§ 3º e 4º."}, {"id": 1000184, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Medida provisória pode tratar de direito penal?", "verso": "Não.", "explicacao": "CF, art. 62, § 1º, I, b. Também é vedada sobre processo penal, nacionalidade e direitos políticos, entre outros temas."}, {"id": 1000185, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quantos ministros tem o STF e como são nomeados?", "verso": "11 ministros, brasileiros natos, com mais de 35 e menos de 70 anos, nomeados pelo Presidente após aprovação pela maioria absoluta do Senado.", "explicacao": "CF, art. 101."}, {"id": 1000186, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quais as garantias dos juízes?", "verso": "Vitaliciedade, inamovibilidade e irredutibilidade de subsídio.", "explicacao": "CF, art. 95."}, {"id": 1000187, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Qual o efeito da súmula vinculante?", "verso": "Vincula os demais órgãos do Judiciário e a administração pública direta e indireta, em todas as esferas.", "explicacao": "CF, art. 103-A. Aprovada por 2/3 dos membros do STF."}, {"id": 1000188, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "Quais as garantias dos membros do Ministério Público?", "verso": "Vitaliciedade, inamovibilidade e irredutibilidade de subsídio.", "explicacao": "CF, art. 128, § 5º, I."}, {"id": 1000189, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "O que a Constituição atribui ao MP sobre a atividade policial?", "verso": "O controle externo da atividade policial.", "explicacao": "CF, art. 129, VII."}, {"id": 1000190, "trilha": "policial", "materia": "const", "assunto": "Direitos sociais", "tipo": "pergunta", "frente": "Quais são os direitos sociais do art. 6º?", "verso": "Educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância e assistência aos desamparados.", "explicacao": "CF, art. 6º."}, {"id": 1000191, "trilha": "policial", "materia": "const", "assunto": "Ordem social", "tipo": "pergunta", "frente": "Qual o dever da família, da sociedade e do Estado com a criança e o adolescente?", "verso": "Assegurar, com absoluta prioridade, seus direitos fundamentais, e colocá-los a salvo de negligência, discriminação, exploração, violência, crueldade e opressão.", "explicacao": "CF, art. 227."}, {"id": 1000192, "trilha": "policial", "materia": "const", "assunto": "Ordem social", "tipo": "pergunta", "frente": "Qual a idade da inimputabilidade penal na Constituição?", "verso": "Menores de 18 anos são penalmente inimputáveis, sujeitos à legislação especial.", "explicacao": "CF, art. 228."}, {"id": 1000193, "trilha": "policial", "materia": "const", "assunto": "Militares", "tipo": "pergunta", "frente": "Os militares podem se sindicalizar ou fazer greve?", "verso": "Não. São proibidas a sindicalização e a greve.", "explicacao": "CF, art. 142, § 3º, IV (aplicável aos militares dos Estados pelo art. 42, § 1º)."}, {"id": 1000194, "trilha": "policial", "materia": "const", "assunto": "Militares", "tipo": "pergunta", "frente": "Cabe habeas corpus contra punição disciplinar militar?", "verso": "Não cabe quanto ao mérito da punição, mas cabe para discutir sua legalidade (pressupostos formais).", "explicacao": "CF, art. 142, § 2º, e jurisprudência do STF."}, {"id": 1000195, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pares", "frente": "Porte para consumo (art. 28) x tráfico (art. 33): como o juiz diferencia?", "verso": "Pela natureza e quantidade da substância, local e condições da ação, circunstâncias sociais e pessoais, conduta e antecedentes do agente.", "explicacao": "Lei 11.343/2006, art. 28, § 2º."}, {"id": 1000196, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quais as penas para o porte de droga para consumo pessoal?", "verso": "Advertência sobre os efeitos das drogas, prestação de serviços à comunidade e medida educativa de comparecimento a programa ou curso. Não há pena de prisão.", "explicacao": "Lei 11.343/2006, art. 28. O STF (RE 635.659) fixou 40 g ou 6 plantas fêmeas como presunção relativa de uso, para a maconha."}, {"id": 1000197, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Qual a pena do tráfico de drogas (art. 33)?", "verso": "Reclusão de 5 a 15 anos e multa.", "explicacao": "Lei 11.343/2006, art. 33, caput."}, {"id": 1000198, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quais os requisitos do tráfico privilegiado?", "verso": "Agente primário, de bons antecedentes, que não se dedique a atividades criminosas nem integre organização criminosa. Reduz a pena de 1/6 a 2/3.", "explicacao": "Lei 11.343/2006, art. 33, § 4º. O STF entende que não é hediondo."}, {"id": 1000199, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Associação para o tráfico exige quantas pessoas?", "verso": "Duas ou mais, associadas de forma estável e permanente.", "explicacao": "Lei 11.343/2006, art. 35. Pena de 3 a 10 anos."}, {"id": 1000200, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Oferecer droga, eventualmente e sem lucro, a pessoa do seu relacionamento, para consumirem juntos, é crime?", "verso": "Sim, crime de menor potencial ofensivo: detenção de 6 meses a 1 ano e multa, sem prejuízo das penas do art. 28.", "explicacao": "Lei 11.343/2006, art. 33, § 3º."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select count(*) as cartoes_policial_no_banco from public.cartoes where trilha = 'policial' and ativa;
